options.getOption:
// Business Charts (volkovlabs-echarts-panel) "Get Option" function body.
// Smoothed wind view: a continuous gust curve (mph) plus a SPARSE set of
// direction arrows riding on the curve. Each arrow summarises one time-bin:
//   y      = mean gust in the bin (sits on the smoothed line)
//   colour = gust magnitude (green low -> orange/red high)
//   angle  = circular-mean wind direction for the bin
// Direction from the exporter is METEOROLOGICAL (bearing the wind blows FROM);
// the arrow points the way the wind BLOWS TO, i.e. (from + 180). Tune ARROW_TO
// (0 = point the way wind comes FROM) and N_ARROWS (arrow density) here.
const ARROW_TO = 180;
const N_ARROWS = 24;

// --- pull the panel data frames -------------------------------------------
const pd = (typeof data !== 'undefined' && data && data.series)
  ? data
  : (context && context.panel && context.panel.data) || { series: [] };
const series = pd.series || [];

const vals = (f) => (f && f.values && f.values.toArray) ? f.values.toArray() : (f ? f.values : []);
const frame = (ref) => series.find((s) => s.refId === ref) || null;
const tField = (fr) => fr && fr.fields.find((f) => f.type === 'time');
const nField = (fr) => fr && fr.fields.find((f) => f.type === 'number');

const gustF = frame('A');
const dirF = frame('B');

const gT = vals(tField(gustF));
const gV = vals(nField(gustF));
const dT = vals(tField(dirF));
const dV = vals(nField(dirF));

// direction, keyed by timestamp, with a nearest-time fallback
const dirByT = new Map();
const dSorted = [];
for (let i = 0; i < dT.length; i++) {
  const t = +dT[i];
  dirByT.set(t, dV[i]);
  dSorted.push([t, dV[i]]);
}
dSorted.sort((a, b) => a[0] - b[0]);
const nearestDir = (t) => {
  if (dirByT.has(t)) return dirByT.get(t);
  let best = null, bd = Infinity;
  for (let i = 0; i < dSorted.length; i++) {
    const d = Math.abs(dSorted[i][0] - t);
    if (d < bd) { bd = d; best = dSorted[i][1]; }
    else if (dSorted[i][0] > t) break;
  }
  return best;
};

const POINTS16 = ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'];
const compass = (deg) => POINTS16[Math.round((((deg % 360) + 360) % 360) / 22.5) % 16];

// --- continuous gust line + per-sample direction --------------------------
let maxG = 1;
const line = [];
const samp = []; // {t, g, dir} for well-formed samples, used for binning
for (let i = 0; i < gT.length; i++) {
  const g = gV[i];
  if (g == null || !isFinite(g)) continue;
  const t = +gT[i];
  line.push([t, g]);
  if (g > maxG) maxG = g;
  let dir = nearestDir(t);
  if (dir != null && isFinite(dir)) {
    dir = (((dir % 360) + 360) % 360);
    samp.push({ t: t, g: g, dir: dir });
  }
}

// --- downsample to N_ARROWS bins, circular-mean the direction -------------
const arrows = [];
const n = samp.length;
const bins = Math.min(N_ARROWS, n);
for (let b = 0; b < bins; b++) {
  const lo = Math.floor((b * n) / bins);
  const hi = Math.floor(((b + 1) * n) / bins);
  if (hi <= lo) continue;
  let sumT = 0, sumG = 0, sx = 0, cy = 0, cnt = 0;
  for (let i = lo; i < hi; i++) {
    const s = samp[i];
    sumT += s.t; sumG += s.g;
    sx += Math.sin(s.dir * Math.PI / 180);
    cy += Math.cos(s.dir * Math.PI / 180);
    cnt++;
  }
  const mt = sumT / cnt;
  const mg = sumG / cnt;
  let mdir = Math.atan2(sx / cnt, cy / cnt) * 180 / Math.PI;
  mdir = ((mdir % 360) + 360) % 360;
  arrows.push({
    value: [mt, mg],
    symbolRotate: -((mdir + ARROW_TO) % 360),
    dir: mdir,
  });
}

const axisText = '#c7ccd4';
const axisLine = '#8891a0';

return {
  backgroundColor: 'transparent',
  animation: false,
  grid: { left: 52, right: 18, top: 16, bottom: 34 },
  tooltip: {
    trigger: 'item',
    axisPointer: { type: 'cross' },
    formatter: (p) => {
      const d = new Date(p.value[0]);
      const hh = String(d.getHours()).padStart(2, '0');
      const mm = String(d.getMinutes()).padStart(2, '0');
      let s = hh + ':' + mm + '<br/>Gust: <b>' + p.value[1].toFixed(1) + ' mph</b>';
      if (p.data && p.data.dir != null) {
        s += '<br/>From: <b>' + compass(p.data.dir) + '</b> (' + Math.round(p.data.dir) + '°)';
      }
      return s;
    },
  },
  visualMap: {
    show: false,
    type: 'continuous',
    dimension: 1,
    min: 0,
    max: Math.max(15, Math.ceil(maxG)),
    seriesIndex: 1,
    inRange: { color: ['#22e84a', '#a3e635', '#eab308', '#f59e0b', '#f97316', '#ef4444'] },
  },
  xAxis: {
    type: 'time',
    axisLine: { lineStyle: { color: axisLine } },
    axisLabel: { color: axisText, hideOverlap: true },
    splitLine: { show: false },
  },
  yAxis: {
    type: 'value',
    name: 'MPH',
    min: 0,
    nameTextStyle: { color: axisText },
    axisLine: { show: true, lineStyle: { color: axisLine } },
    axisLabel: { color: axisText },
    splitLine: { lineStyle: { color: 'rgba(136,145,160,0.15)' } },
  },
  series: [
    {
      type: 'line',
      data: line,
      smooth: 0.4,
      showSymbol: false,
      silent: true,
      z: 1,
      lineStyle: { color: 'rgba(147,180,255,0.60)', width: 2 },
      areaStyle: {
        color: {
          type: 'linear', x: 0, y: 0, x2: 0, y2: 1,
          colorStops: [
            { offset: 0, color: 'rgba(147,180,255,0.08)' },
            { offset: 1, color: 'rgba(91,141,239,0.00)' },
          ],
        },
      },
    },
    {
      type: 'scatter',
      symbol: 'path://M12 2 L20 22 L12 17 L4 22 Z',
      symbolSize: 14,
      symbolKeepAspect: true,
      z: 2,
      data: arrows,
    },
  ],
};
